from .common import make_sol

LINKED_LIST_SOLUTIONS = {
    'introduction-to-singly-linkedlist': make_sol('class Node {\n    int data;\n    Node next;\n    Node(int d) { data = d; next = null; }\n}\n\npublic class Solution {\n    public static Node constructLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            curr.next = new Node(arr[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'class Node {\n    int data;\n    Node next;\n    Node(int d) { data = d; next = null; }\n}\n\npublic class Solution {\n    public static Node constructLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            curr.next = new Node(arr[i]);\n            curr = curr.next;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)'),

    'traversal-in-linked-list': make_sol('public class Solution {\n    public static void printList(Node head) {\n        Node curr = head;\n        while (curr != null) {\n            System.out.print(curr.data + " ");\n            curr = curr.next;\n        }\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static void printList(Node head) {\n        Node curr = head;\n        while (curr != null) {\n            System.out.print(curr.data + " ");\n            curr = curr.next;\n        }\n    }\n}', 'O(N)', 'O(1)'),

    'deletion-in-linked-list': make_sol('public class Solution {\n    public static Node deleteNode(Node head, int position) {\n        if (head == null) return null;\n        if (position == 1) return head.next;\n        Node curr = head;\n        for (int i = 1; curr != null && i < position - 1; i++) {\n            curr = curr.next;\n        }\n        if (curr == null || curr.next == null) return head;\n        curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteNode(Node head, int position) {\n        if (head == null) return null;\n        if (position == 1) return head.next;\n        Node curr = head;\n        for (int i = 1; curr != null && i < position - 1; i++) {\n            curr = curr.next;\n        }\n        if (curr == null || curr.next == null) return head;\n        curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'insertion-in-linked-list': make_sol('public class Solution {\n    public static Node insertAtEnd(Node head, int x) {\n        if (head == null) return new Node(x);\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.next = new Node(x);\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node insertAtEnd(Node head, int x) {\n        if (head == null) return new Node(x);\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.next = new Node(x);\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'deletion-of-the-head-of-ll': make_sol('public class Solution {\n    public static Node deleteHead(Node head) {\n        if (head == null) return null;\n        return head.next;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static Node deleteHead(Node head) {\n        if (head == null) return null;\n        return head.next;\n    }\n}', 'O(1)', 'O(1)'),

    'deletion-of-the-tail-of-ll': make_sol('public class Solution {\n    public static Node deleteTail(Node head) {\n        if (head == null || head.next == null) return null;\n        Node curr = head;\n        while (curr.next.next != null) curr = curr.next;\n        curr.next = null;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteTail(Node head) {\n        if (head == null || head.next == null) return null;\n        Node curr = head;\n        while (curr.next.next != null) curr = curr.next;\n        curr.next = null;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'deletion-of-the-kth-element-of-ll': make_sol('public class Solution {\n    public static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) return head.next;\n        Node curr = head;\n        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;\n        if (curr != null && curr.next != null) curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(K)', 'O(1)', 'public class Solution {\n    public static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) return head.next;\n        Node curr = head;\n        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;\n        if (curr != null && curr.next != null) curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(K)', 'O(1)'),

    'delete-the-element-with-value-x': make_sol('public class Solution {\n    public static Node deleteVal(Node head, int val) {\n        if (head == null) return null;\n        if (head.data == val) return head.next;\n        Node curr = head;\n        while (curr.next != null && curr.next.data != val) curr = curr.next;\n        if (curr.next != null) curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteVal(Node head, int val) {\n        if (head == null) return null;\n        if (head.data == val) return head.next;\n        Node curr = head;\n        while (curr.next != null && curr.next.data != val) curr = curr.next;\n        if (curr.next != null) curr.next = curr.next.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'insertion-at-the-head-of-ll': make_sol('public class Solution {\n    public static Node insertHead(Node head, int val) {\n        Node newNode = new Node(val);\n        newNode.next = head;\n        return newNode;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static Node insertHead(Node head, int val) {\n        Node newNode = new Node(val);\n        newNode.next = head;\n        return newNode;\n    }\n}', 'O(1)', 'O(1)'),

    'insertion-at-the-tail-of-ll': make_sol('public class Solution {\n    public static Node insertTail(Node head, int val) {\n        if (head == null) return new Node(val);\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.next = new Node(val);\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node insertTail(Node head, int val) {\n        if (head == null) return new Node(val);\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.next = new Node(val);\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'insertion-at-the-kth-position-of-ll': make_sol('public class Solution {\n    public static Node insertKth(Node head, int val, int k) {\n        if (head == null) {\n            if (k == 1) return new Node(val);\n            return null;\n        }\n        if (k == 1) {\n            Node n = new Node(val);\n            n.next = head;\n            return n;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;\n        if (curr != null) {\n            Node n = new Node(val);\n            n.next = curr.next;\n            curr.next = n;\n        }\n        return head;\n    }\n}', 'O(K)', 'O(1)', 'public class Solution {\n    public static Node insertKth(Node head, int val, int k) {\n        if (head == null) {\n            if (k == 1) return new Node(val);\n            return null;\n        }\n        if (k == 1) {\n            Node n = new Node(val);\n            n.next = head;\n            return n;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k - 1; i++) curr = curr.next;\n        if (curr != null) {\n            Node n = new Node(val);\n            n.next = curr.next;\n            curr.next = n;\n        }\n        return head;\n    }\n}', 'O(K)', 'O(1)'),

    'insertion-before-the-value-x-in-ll': make_sol('public class Solution {\n    public static Node insertBeforeVal(Node head, int val, int x) {\n        if (head == null) return null;\n        if (head.data == x) {\n            Node n = new Node(val);\n            n.next = head;\n            return n;\n        }\n        Node curr = head;\n        while (curr.next != null && curr.next.data != x) curr = curr.next;\n        if (curr.next != null) {\n            Node n = new Node(val);\n            n.next = curr.next;\n            curr.next = n;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node insertBeforeVal(Node head, int val, int x) {\n        if (head == null) return null;\n        if (head.data == x) {\n            Node n = new Node(val);\n            n.next = head;\n            return n;\n        }\n        Node curr = head;\n        while (curr.next != null && curr.next.data != x) curr = curr.next;\n        if (curr.next != null) {\n            Node n = new Node(val);\n            n.next = curr.next;\n            curr.next = n;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'find-the-length-of-the-linked-list': make_sol('public class Solution {\n    public static int getCount(Node head) {\n        int count = 0;\n        Node curr = head;\n        while (curr != null) { count++; curr = curr.next; }\n        return count;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static int getCount(Node head) {\n        int count = 0;\n        Node curr = head;\n        while (curr != null) { count++; curr = curr.next; }\n        return count;\n    }\n}', 'O(N)', 'O(1)'),

    'search-in-linked-list': make_sol('public class Solution {\n    public static boolean searchKey(int n, Node head, int key) {\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == key) return true;\n            curr = curr.next;\n        }\n        return false;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static boolean searchKey(int n, Node head, int key) {\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == key) return true;\n            curr = curr.next;\n        }\n        return false;\n    }\n}', 'O(N)', 'O(1)'),

    'introduction-to-doubly-ll': make_sol('class Node {\n    int data;\n    Node next, prev;\n    Node(int x) { data = x; next = null; prev = null; }\n}\n\npublic class Solution {\n    public static Node constructDLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            Node temp = new Node(arr[i]);\n            curr.next = temp;\n            temp.prev = curr;\n            curr = temp;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'class Node {\n    int data;\n    Node next, prev;\n    Node(int x) { data = x; next = null; prev = null; }\n}\n\npublic class Solution {\n    public static Node constructDLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            Node temp = new Node(arr[i]);\n            curr.next = temp;\n            temp.prev = curr;\n            curr = temp;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)'),

    'deletion-in-doubly-ll': make_sol('public class Solution {\n    public static Node deleteNode(Node head, int x) {\n        if (head == null) return null;\n        if (x == 1) {\n            head = head.next;\n            if (head != null) head.prev = null;\n            return head;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < x; i++) curr = curr.next;\n        if (curr == null) return head;\n        if (curr.next != null) curr.next.prev = curr.prev;\n        if (curr.prev != null) curr.prev.next = curr.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteNode(Node head, int x) {\n        if (head == null) return null;\n        if (x == 1) {\n            head = head.next;\n            if (head != null) head.prev = null;\n            return head;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < x; i++) curr = curr.next;\n        if (curr == null) return head;\n        if (curr.next != null) curr.next.prev = curr.prev;\n        if (curr.prev != null) curr.prev.next = curr.next;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'insertion-in-dll': make_sol('public class Solution {\n    public static void addNode(Node head, int pos, int data) {\n        Node curr = head;\n        for (int i = 0; curr != null && i < pos; i++) curr = curr.next;\n        if (curr == null) return;\n        Node newNode = new Node(data);\n        newNode.next = curr.next;\n        newNode.prev = curr;\n        if (curr.next != null) curr.next.prev = newNode;\n        curr.next = newNode;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static void addNode(Node head, int pos, int data) {\n        Node curr = head;\n        for (int i = 0; curr != null && i < pos; i++) curr = curr.next;\n        if (curr == null) return;\n        Node newNode = new Node(data);\n        newNode.next = curr.next;\n        newNode.prev = curr;\n        if (curr.next != null) curr.next.prev = newNode;\n        curr.next = newNode;\n    }\n}', 'O(N)', 'O(1)'),

    'convert-array-to-dll': make_sol('public class Solution {\n    public static Node constructDLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            Node temp = new Node(arr[i]);\n            curr.next = temp;\n            temp.prev = curr;\n            curr = temp;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static Node constructDLL(int[] arr) {\n        if (arr.length == 0) return null;\n        Node head = new Node(arr[0]), curr = head;\n        for (int i = 1; i < arr.length; i++) {\n            Node temp = new Node(arr[i]);\n            curr.next = temp;\n            temp.prev = curr;\n            curr = temp;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(N)'),

    'delete-tail-of-dll': make_sol('public class Solution {\n    public static Node deleteTail(Node head) {\n        if (head == null || head.next == null) return null;\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.prev.next = null;\n        curr.prev = null;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteTail(Node head) {\n        if (head == null || head.next == null) return null;\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        curr.prev.next = null;\n        curr.prev = null;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'delete-kth-element-of-dll': make_sol('public class Solution {\n    public static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) {\n            head = head.next;\n            if (head != null) head.prev = null;\n            return head;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k; i++) curr = curr.next;\n        if (curr != null) {\n            if (curr.next != null) curr.next.prev = curr.prev;\n            if (curr.prev != null) curr.prev.next = curr.next;\n        }\n        return head;\n    }\n}', 'O(K)', 'O(1)', 'public class Solution {\n    public static Node deleteKth(Node head, int k) {\n        if (head == null) return null;\n        if (k == 1) {\n            head = head.next;\n            if (head != null) head.prev = null;\n            return head;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k; i++) curr = curr.next;\n        if (curr != null) {\n            if (curr.next != null) curr.next.prev = curr.prev;\n            if (curr.prev != null) curr.prev.next = curr.next;\n        }\n        return head;\n    }\n}', 'O(K)', 'O(1)'),

    'removing-given-node-in-dll': make_sol('public class Solution {\n    public static void deleteNode(Node node) {\n        if (node.prev != null) node.prev.next = node.next;\n        if (node.next != null) node.next.prev = node.prev;\n        node.next = null;\n        node.prev = null;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static void deleteNode(Node node) {\n        if (node.prev != null) node.prev.next = node.next;\n        if (node.next != null) node.next.prev = node.prev;\n        node.next = null;\n        node.prev = null;\n    }\n}', 'O(1)', 'O(1)'),

    'insert-node-before-head-in-dll': make_sol('public class Solution {\n    public static Node insertBeforeHead(Node head, int val) {\n        Node newNode = new Node(val);\n        if (head == null) return newNode;\n        newNode.next = head;\n        head.prev = newNode;\n        return newNode;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static Node insertBeforeHead(Node head, int val) {\n        Node newNode = new Node(val);\n        if (head == null) return newNode;\n        newNode.next = head;\n        head.prev = newNode;\n        return newNode;\n    }\n}', 'O(1)', 'O(1)'),

    'insert-node-before-tail-in-dll': make_sol('public class Solution {\n    public static Node insertBeforeTail(Node head, int val) {\n        if (head == null || head.next == null) {\n            Node n = new Node(val);\n            n.next = head;\n            if (head != null) head.prev = n;\n            return n;\n        }\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        Node newNode = new Node(val);\n        newNode.prev = curr.prev;\n        newNode.next = curr;\n        curr.prev.next = newNode;\n        curr.prev = newNode;\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node insertBeforeTail(Node head, int val) {\n        if (head == null || head.next == null) {\n            Node n = new Node(val);\n            n.next = head;\n            if (head != null) head.prev = n;\n            return n;\n        }\n        Node curr = head;\n        while (curr.next != null) curr = curr.next;\n        Node newNode = new Node(val);\n        newNode.prev = curr.prev;\n        newNode.next = curr;\n        curr.prev.next = newNode;\n        curr.prev = newNode;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'insert-node-before-kth-node-in-dll': make_sol('public class Solution {\n    public static Node insertBeforeKth(Node head, int k, int val) {\n        if (k == 1) {\n            Node n = new Node(val);\n            n.next = head;\n            if (head != null) head.prev = n;\n            return n;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k; i++) curr = curr.next;\n        if (curr == null) return head;\n        Node newNode = new Node(val);\n        newNode.prev = curr.prev;\n        newNode.next = curr;\n        curr.prev.next = newNode;\n        curr.prev = newNode;\n        return head;\n    }\n}', 'O(K)', 'O(1)', 'public class Solution {\n    public static Node insertBeforeKth(Node head, int k, int val) {\n        if (k == 1) {\n            Node n = new Node(val);\n            n.next = head;\n            if (head != null) head.prev = n;\n            return n;\n        }\n        Node curr = head;\n        for (int i = 1; curr != null && i < k; i++) curr = curr.next;\n        if (curr == null) return head;\n        Node newNode = new Node(val);\n        newNode.prev = curr.prev;\n        newNode.next = curr;\n        curr.prev.next = newNode;\n        curr.prev = newNode;\n        return head;\n    }\n}', 'O(K)', 'O(1)'),

    'insert-before-given-node-in-dll': make_sol('public class Solution {\n    public static void insertBeforeNode(Node node, int val) {\n        Node prev = node.prev;\n        Node newNode = new Node(val);\n        newNode.next = node;\n        newNode.prev = prev;\n        if (prev != null) prev.next = newNode;\n        node.prev = newNode;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static void insertBeforeNode(Node node, int val) {\n        Node prev = node.prev;\n        Node newNode = new Node(val);\n        newNode.next = node;\n        newNode.prev = prev;\n        if (prev != null) prev.next = newNode;\n        node.prev = newNode;\n    }\n}', 'O(1)', 'O(1)'),

    'delete-head-of-dll': make_sol('public class Solution {\n    public static Node deleteHead(Node head) {\n        if (head == null || head.next == null) return null;\n        head = head.next;\n        head.prev = null;\n        return head;\n    }\n}', 'O(1)', 'O(1)', 'public class Solution {\n    public static Node deleteHead(Node head) {\n        if (head == null || head.next == null) return null;\n        head = head.next;\n        head.prev = null;\n        return head;\n    }\n}', 'O(1)', 'O(1)'),

    'reverse-a-doubly-linked-list': make_sol('import java.util.Stack;\n\npublic class Solution {\n    public static Node reverseDLL(Node head) {\n        Stack<Integer> st = new Stack<>();\n        Node curr = head;\n        while (curr != null) { st.push(curr.data); curr = curr.next; }\n        curr = head;\n        while (curr != null) { curr.data = st.pop(); curr = curr.next; }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static Node reverseDLL(Node head) {\n        if (head == null || head.next == null) return head;\n        Node curr = head, prev = null;\n        while (curr != null) {\n            prev = curr.prev;\n            curr.prev = curr.next;\n            curr.next = prev;\n            curr = curr.prev;\n        }\n        return prev.prev;\n    }\n}', 'O(N)', 'O(1)'),

    'add-two-numbers-in-ll': make_sol('public class Solution {\n    public static ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0), curr = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int sum = carry;\n            if (l1 != null) { sum += l1.val; l1 = l1.next; }\n            if (l2 != null) { sum += l2.val; l2 = l2.next; }\n            carry = sum / 10;\n            curr.next = new ListNode(sum % 10);\n            curr = curr.next;\n        }\n        return dummy.next;\n    }\n}', 'O(max(N, M))', 'O(max(N, M))', 'public class Solution {\n    public static ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0), curr = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int sum = carry;\n            if (l1 != null) { sum += l1.val; l1 = l1.next; }\n            if (l2 != null) { sum += l2.val; l2 = l2.next; }\n            carry = sum / 10;\n            curr.next = new ListNode(sum % 10);\n            curr = curr.next;\n        }\n        return dummy.next;\n    }\n}', 'O(max(N, M))', 'O(max(N, M))'),

    'segregate-odd-and-even-nodes-in-ll': make_sol('import java.util.ArrayList;\n\npublic class Solution {\n    public static ListNode oddEvenList(ListNode head) {\n        if (head == null) return null;\n        ArrayList<Integer> arr = new ArrayList<>();\n        ListNode temp = head;\n        while (temp != null) { arr.add(temp.val); if (temp.next != null) temp = temp.next.next; else break; }\n        temp = head.next;\n        while (temp != null) { arr.add(temp.val); if (temp.next != null) temp = temp.next.next; else break; }\n        temp = head; int i = 0;\n        while (temp != null) { temp.val = arr.get(i++); temp = temp.next; }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static ListNode oddEvenList(ListNode head) {\n        if (head == null || head.next == null) return head;\n        ListNode odd = head, even = head.next, evenHead = even;\n        while (even != null && even.next != null) {\n            odd.next = even.next;\n            odd = odd.next;\n            even.next = odd.next;\n            even = even.next;\n        }\n        odd.next = evenHead;\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    "sort-a-ll-of-0's-1's-and-2's": make_sol('public class Solution {\n    public static Node segregate(Node head) {\n        int c0 = 0, c1 = 0, c2 = 0;\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == 0) c0++;\n            else if (curr.data == 1) c1++;\n            else c2++;\n            curr = curr.next;\n        }\n        curr = head;\n        while (c0-- > 0) { curr.data = 0; curr = curr.next; }\n        while (c1-- > 0) { curr.data = 1; curr = curr.next; }\n        while (c2-- > 0) { curr.data = 2; curr = curr.next; }\n        return head;\n    }\n}', 'O(2N)', 'O(1)', 'public class Solution {\n    public static Node segregate(Node head) {\n        Node zeroD = new Node(0), oneD = new Node(0), twoD = new Node(0);\n        Node zero = zeroD, one = oneD, two = twoD;\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == 0) { zero.next = curr; zero = zero.next; }\n            else if (curr.data == 1) { one.next = curr; one = one.next; }\n            else { two.next = curr; two = two.next; }\n            curr = curr.next;\n        }\n        zero.next = (oneD.next != null) ? oneD.next : twoD.next;\n        one.next = twoD.next;\n        two.next = null;\n        return zeroD.next;\n    }\n}', 'O(N)', 'O(1)'),

    'remove-nth-node-from-the-back-of-the-ll': make_sol('public class Solution {\n    public static ListNode removeNthFromEnd(ListNode head, int n) {\n        int len = 0;\n        ListNode temp = head;\n        while (temp != null) { len++; temp = temp.next; }\n        if (len == n) return head.next;\n        temp = head;\n        for (int i = 1; i < len - n; i++) temp = temp.next;\n        temp.next = temp.next.next;\n        return head;\n    }\n}', 'O(2N)', 'O(1)', 'public class Solution {\n    public static ListNode removeNthFromEnd(ListNode head, int n) {\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode fast = dummy, slow = dummy;\n        for (int i = 0; i <= n; i++) fast = fast.next;\n        while (fast != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n        return dummy.next;\n    }\n}', 'O(N)', 'O(1)'),

    'reverse-a-ll': make_sol('import java.util.Stack;\n\npublic class Solution {\n    public static ListNode reverseList(ListNode head) {\n        if (head == null) return null;\n        Stack<Integer> st = new Stack<>();\n        ListNode temp = head;\n        while (temp != null) { st.push(temp.val); temp = temp.next; }\n        temp = head;\n        while (temp != null) { temp.val = st.pop(); temp = temp.next; }\n        return head;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static ListNode reverseList(ListNode head) {\n        ListNode prev = null, curr = head;\n        while (curr != null) {\n            ListNode next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n        }\n        return prev;\n    }\n}', 'O(N)', 'O(1)'),

    'add-one-to-a-number-represented-by-ll': make_sol('public class Solution {\n    public static Node addOne(Node head) {\n        head = reverse(head);\n        Node curr = head;\n        int carry = 1;\n        while (curr != null) {\n            int sum = curr.data + carry;\n            curr.data = sum % 10;\n            carry = sum / 10;\n            if (curr.next == null && carry > 0) {\n                curr.next = new Node(carry);\n                carry = 0;\n            }\n            curr = curr.next;\n        }\n        return reverse(head);\n    }\n\n    private static Node reverse(Node head) {\n        Node prev = null, curr = head;\n        while (curr != null) {\n            Node next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n        }\n        return prev;\n    }\n}', 'O(3N)', 'O(1)', 'public class Solution {\n    public static Node addOne(Node head) {\n        int carry = helper(head);\n        if (carry == 1) {\n            Node newHead = new Node(1);\n            newHead.next = head;\n            return newHead;\n        }\n        return head;\n    }\n\n    private static int helper(Node temp) {\n        if (temp == null) return 1;\n        int carry = helper(temp.next);\n        temp.data += carry;\n        if (temp.data < 10) return 0;\n        temp.data = 0;\n        return 1;\n    }\n}', 'O(N)', 'O(N)'),

    'find-middle-of-linked-list': make_sol('public class Solution {\n    public static ListNode middleNode(ListNode head) {\n        int len = 0;\n        ListNode temp = head;\n        while (temp != null) { len++; temp = temp.next; }\n        temp = head;\n        for (int i = 0; i < len / 2; i++) temp = temp.next;\n        return temp;\n    }\n}', 'O(N + N/2)', 'O(1)', 'public class Solution {\n    public static ListNode middleNode(ListNode head) {\n        ListNode slow = head, fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        return slow;\n    }\n}', 'O(N/2)', 'O(1)'),

    'delete-the-middle-node-in-ll': make_sol('public class Solution {\n    public static ListNode deleteMiddle(ListNode head) {\n        if (head == null || head.next == null) return null;\n        int len = 0;\n        ListNode temp = head;\n        while (temp != null) { len++; temp = temp.next; }\n        temp = head;\n        for (int i = 0; i < (len / 2) - 1; i++) temp = temp.next;\n        temp.next = temp.next.next;\n        return head;\n    }\n}', 'O(N + N/2)', 'O(1)', 'public class Solution {\n    public static ListNode deleteMiddle(ListNode head) {\n        if (head == null || head.next == null) return null;\n        ListNode slow = head, fast = head, prev = null;\n        while (fast != null && fast.next != null) {\n            prev = slow;\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        prev.next = slow.next;\n        return head;\n    }\n}', 'O(N/2)', 'O(1)'),

    'check-if-ll-is-palindrome-or-not': make_sol('import java.util.Stack;\n\npublic class Solution {\n    public static boolean isPalindrome(ListNode head) {\n        Stack<Integer> st = new Stack<>();\n        ListNode temp = head;\n        while (temp != null) { st.push(temp.val); temp = temp.next; }\n        temp = head;\n        while (temp != null) {\n            if (temp.val != st.pop()) return false;\n            temp = temp.next;\n        }\n        return true;\n    }\n}', 'O(2N)', 'O(N)', 'public class Solution {\n    public static boolean isPalindrome(ListNode head) {\n        if (head == null || head.next == null) return true;\n        ListNode slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode secondHalf = reverse(slow.next);\n        ListNode firstHalf = head;\n        while (secondHalf != null) {\n            if (firstHalf.val != secondHalf.val) return false;\n            firstHalf = firstHalf.next;\n            secondHalf = secondHalf.next;\n        }\n        return true;\n    }\n\n    private static ListNode reverse(ListNode head) {\n        ListNode prev = null, curr = head;\n        while (curr != null) {\n            ListNode next = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = next;\n        }\n        return prev;\n    }\n}', 'O(2N)', 'O(1)'),

    'find-the-intersection-point-of-y-ll': make_sol('import java.util.HashSet;\nimport java.util.Set;\n\npublic class Solution {\n    public static ListNode getIntersectionNode(ListNode headA, ListNode headB) {\n        Set<ListNode> set = new HashSet<>();\n        while (headA != null) { set.add(headA); headA = headA.next; }\n        while (headB != null) {\n            if (set.contains(headB)) return headB;\n            headB = headB.next;\n        }\n        return null;\n    }\n}', 'O(N + M)', 'O(N)', 'public class Solution {\n    public static ListNode getIntersectionNode(ListNode headA, ListNode headB) {\n        if (headA == null || headB == null) return null;\n        ListNode a = headA, b = headB;\n        while (a != b) {\n            a = (a == null) ? headB : a.next;\n            b = (b == null) ? headA : b.next;\n        }\n        return a;\n    }\n}', 'O(2 * max(N, M))', 'O(1)'),

    'detect-a-loop-in-ll': make_sol('import java.util.HashSet;\nimport java.util.Set;\n\npublic class Solution {\n    public static boolean hasCycle(ListNode head) {\n        Set<ListNode> set = new HashSet<>();\n        while (head != null) {\n            if (set.contains(head)) return true;\n            set.add(head);\n            head = head.next;\n        }\n        return false;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static boolean hasCycle(ListNode head) {\n        if (head == null) return false;\n        ListNode slow = head, fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) return true;\n        }\n        return false;\n    }\n}', 'O(N)', 'O(1)'),

    'find-the-starting-point-in-ll': make_sol('import java.util.HashSet;\nimport java.util.Set;\n\npublic class Solution {\n    public static ListNode detectCycle(ListNode head) {\n        Set<ListNode> set = new HashSet<>();\n        while (head != null) {\n            if (set.contains(head)) return head;\n            set.add(head);\n            head = head.next;\n        }\n        return null;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static ListNode detectCycle(ListNode head) {\n        if (head == null || head.next == null) return null;\n        ListNode slow = head, fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                slow = head;\n                while (slow != fast) {\n                    slow = slow.next;\n                    fast = fast.next;\n                }\n                return slow;\n            }\n        }\n        return null;\n    }\n}', 'O(N)', 'O(1)'),

    'length-of-loop-in-ll': make_sol('import java.util.HashMap;\nimport java.util.Map;\n\npublic class Solution {\n    public static int countNodesinLoop(Node head) {\n        Map<Node, Integer> map = new HashMap<>();\n        Node temp = head;\n        int timer = 0;\n        while (temp != null) {\n            if (map.containsKey(temp)) return timer - map.get(temp);\n            map.put(temp, timer++);\n            temp = temp.next;\n        }\n        return 0;\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static int countNodesinLoop(Node head) {\n        Node slow = head, fast = head;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                int count = 1;\n                fast = fast.next;\n                while (slow != fast) { count++; fast = fast.next; }\n                return count;\n            }\n        }\n        return 0;\n    }\n}', 'O(N)', 'O(1)'),

    'reverse-ll-in-group-of-given-size-k': make_sol('public class Solution {\n    public static ListNode reverseKGroup(ListNode head, int k) {\n        if (head == null || k == 1) return head;\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode curr = dummy, nex = dummy, pre = dummy;\n        int count = 0;\n        while (curr.next != null) { curr = curr.next; count++; }\n        while (count >= k) {\n            curr = pre.next;\n            nex = curr.next;\n            for (int i = 1; i < k; i++) {\n                curr.next = nex.next;\n                nex.next = pre.next;\n                pre.next = nex;\n                nex = curr.next;\n            }\n            pre = curr;\n            count -= k;\n        }\n        return dummy.next;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static ListNode reverseKGroup(ListNode head, int k) {\n        if (head == null || k == 1) return head;\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode curr = dummy, nex = dummy, pre = dummy;\n        int count = 0;\n        while (curr.next != null) { curr = curr.next; count++; }\n        while (count >= k) {\n            curr = pre.next;\n            nex = curr.next;\n            for (int i = 1; i < k; i++) {\n                curr.next = nex.next;\n                nex.next = pre.next;\n                pre.next = nex;\n                nex = curr.next;\n            }\n            pre = curr;\n            count -= k;\n        }\n        return dummy.next;\n    }\n}', 'O(N)', 'O(1)'),

    'rotate-a-ll': make_sol('public class Solution {\n    public static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) return head;\n        int len = 1;\n        ListNode curr = head;\n        while (curr.next != null) { len++; curr = curr.next; }\n        k = k % len;\n        if (k == 0) return head;\n        curr.next = head;\n        for (int i = 0; i < len - k; i++) curr = curr.next;\n        head = curr.next;\n        curr.next = null;\n        return head;\n    }\n}', 'O(2N)', 'O(1)', 'public class Solution {\n    public static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) return head;\n        int len = 1;\n        ListNode curr = head;\n        while (curr.next != null) { len++; curr = curr.next; }\n        k = k % len;\n        if (k == 0) return head;\n        curr.next = head;\n        for (int i = 0; i < len - k; i++) curr = curr.next;\n        head = curr.next;\n        curr.next = null;\n        return head;\n    }\n}', 'O(2N)', 'O(1)'),

    'merge-sorted-lists-': make_sol('public class Solution {\n    public static ListNode mergeTwoLists(ListNode list1, ListNode list2) {\n        ListNode dummy = new ListNode(0), curr = dummy;\n        while (list1 != null && list2 != null) {\n            if (list1.val <= list2.val) {\n                curr.next = list1;\n                list1 = list1.next;\n            } else {\n                curr.next = list2;\n                list2 = list2.next;\n            }\n            curr = curr.next;\n        }\n        curr.next = (list1 != null) ? list1 : list2;\n        return dummy.next;\n    }\n}', 'O(N + M)', 'O(1)', 'public class Solution {\n    public static ListNode mergeTwoLists(ListNode list1, ListNode list2) {\n        ListNode dummy = new ListNode(0), curr = dummy;\n        while (list1 != null && list2 != null) {\n            if (list1.val <= list2.val) {\n                curr.next = list1;\n                list1 = list1.next;\n            } else {\n                curr.next = list2;\n                list2 = list2.next;\n            }\n            curr = curr.next;\n        }\n        curr.next = (list1 != null) ? list1 : list2;\n        return dummy.next;\n    }\n}', 'O(N + M)', 'O(1)'),

    'flattening-of-ll': make_sol('public class Solution {\n    static class Node {\n        int data;\n        Node next, bottom;\n        Node(int d) { data = d; next = null; bottom = null; }\n    }\n\n    public static Node flatten(Node root) {\n        if (root == null || root.next == null) return root;\n        root.next = flatten(root.next);\n        root = merge(root, root.next);\n        return root;\n    }\n\n    private static Node merge(Node a, Node b) {\n        Node dummy = new Node(0), res = dummy;\n        while (a != null && b != null) {\n            if (a.data < b.data) { res.bottom = a; res = a; a = a.bottom; }\n            else { res.bottom = b; res = b; b = b.bottom; }\n        }\n        if (a != null) res.bottom = a;\n        else res.bottom = b;\n        return dummy.bottom;\n    }\n}', 'O(N * M)', 'O(N)', 'public class Solution {\n    static class Node {\n        int data;\n        Node next, bottom;\n        Node(int d) { data = d; next = null; bottom = null; }\n    }\n\n    public static Node flatten(Node root) {\n        if (root == null || root.next == null) return root;\n        root.next = flatten(root.next);\n        root = merge(root, root.next);\n        return root;\n    }\n\n    private static Node merge(Node a, Node b) {\n        Node dummy = new Node(0), res = dummy;\n        while (a != null && b != null) {\n            if (a.data < b.data) { res.bottom = a; res = a; a = a.bottom; }\n            else { res.bottom = b; res = b; b = b.bottom; }\n        }\n        if (a != null) res.bottom = a;\n        else res.bottom = b;\n        return dummy.bottom;\n    }\n}', 'O(N * M)', 'O(N)'),

    'sort-ll': make_sol('import java.util.*;\n\npublic class Solution {\n    public static ListNode sortList(ListNode head) {\n        List<Integer> list = new ArrayList<>();\n        ListNode temp = head;\n        while (temp != null) { list.add(temp.val); temp = temp.next; }\n        Collections.sort(list);\n        temp = head; int i = 0;\n        while (temp != null) { temp.val = list.get(i++); temp = temp.next; }\n        return head;\n    }\n}', 'O(N log N)', 'O(N)', 'public class Solution {\n    public static ListNode sortList(ListNode head) {\n        if (head == null || head.next == null) return head;\n        ListNode mid = getMid(head);\n        ListNode right = mid.next;\n        mid.next = null;\n        ListNode leftSorted = sortList(head);\n        ListNode rightSorted = sortList(right);\n        return merge(leftSorted, rightSorted);\n    }\n\n    private static ListNode getMid(ListNode head) {\n        ListNode slow = head, fast = head.next;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        return slow;\n    }\n\n    private static ListNode merge(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0), curr = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) { curr.next = l1; l1 = l1.next; }\n            else { curr.next = l2; l2 = l2.next; }\n            curr = curr.next;\n        }\n        curr.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n}', 'O(N log N)', 'O(log N)'),

    'clone-a-ll-with-random-and-next-pointer': make_sol('import java.util.HashMap;\nimport java.util.Map;\n\nclass Node {\n    int val;\n    Node next, random;\n    Node(int val) { this.val = val; this.next = null; this.random = null; }\n}\n\npublic class Solution {\n    public static Node copyRandomList(Node head) {\n        Map<Node, Node> map = new HashMap<>();\n        Node curr = head;\n        while (curr != null) {\n            map.put(curr, new Node(curr.val));\n            curr = curr.next;\n        }\n        curr = head;\n        while (curr != null) {\n            map.get(curr).next = map.get(curr.next);\n            map.get(curr).random = map.get(curr.random);\n            curr = curr.next;\n        }\n        return map.get(head);\n    }\n}', 'O(N)', 'O(N)', 'public class Solution {\n    public static Node copyRandomList(Node head) {\n        if (head == null) return null;\n        Node curr = head;\n        while (curr != null) {\n            Node next = curr.next;\n            Node copy = new Node(curr.val);\n            curr.next = copy;\n            copy.next = next;\n            curr = next;\n        }\n        curr = head;\n        while (curr != null) {\n            if (curr.random != null) curr.next.random = curr.random.next;\n            curr = curr.next.next;\n        }\n        curr = head;\n        Node dummy = new Node(0), copyCurr = dummy;\n        while (curr != null) {\n            copyCurr.next = curr.next;\n            copyCurr = copyCurr.next;\n            curr.next = curr.next.next;\n            curr = curr.next;\n        }\n        return dummy.next;\n    }\n}', 'O(N)', 'O(1)'),

    'delete-all-occurrences-of-a-key-in-dll': make_sol('public class Solution {\n    public static Node deleteAllOccurrences(Node head, int k) {\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == k) {\n                if (curr == head) head = head.next;\n                Node nextNode = curr.next;\n                Node prevNode = curr.prev;\n                if (nextNode != null) nextNode.prev = prevNode;\n                if (prevNode != null) prevNode.next = nextNode;\n                curr = nextNode;\n            } else {\n                curr = curr.next;\n            }\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node deleteAllOccurrences(Node head, int k) {\n        Node curr = head;\n        while (curr != null) {\n            if (curr.data == k) {\n                if (curr == head) head = head.next;\n                Node nextNode = curr.next;\n                Node prevNode = curr.prev;\n                if (nextNode != null) nextNode.prev = prevNode;\n                if (prevNode != null) prevNode.next = nextNode;\n                curr = nextNode;\n            } else {\n                curr = curr.next;\n            }\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'remove-duplicated-from-sorted-dll': make_sol('public class Solution {\n    public static Node removeDuplicates(Node head) {\n        Node curr = head;\n        while (curr != null && curr.next != null) {\n            Node nextNode = curr.next;\n            while (nextNode != null && nextNode.data == curr.data) nextNode = nextNode.next;\n            curr.next = nextNode;\n            if (nextNode != null) nextNode.prev = curr;\n            curr = curr.next;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)', 'public class Solution {\n    public static Node removeDuplicates(Node head) {\n        Node curr = head;\n        while (curr != null && curr.next != null) {\n            Node nextNode = curr.next;\n            while (nextNode != null && nextNode.data == curr.data) nextNode = nextNode.next;\n            curr.next = nextNode;\n            if (nextNode != null) nextNode.prev = curr;\n            curr = curr.next;\n        }\n        return head;\n    }\n}', 'O(N)', 'O(1)'),

    'find-pairs-with-given-sum-in-doubly-linked-list': make_sol('import java.util.*;\n\npublic class Solution {\n    public static ArrayList<ArrayList<Integer>> findPairsWithGivenSum(int target, Node head) {\n        ArrayList<ArrayList<Integer>> ans = new ArrayList<>();\n        Node n1 = head;\n        while (n1 != null) {\n            Node n2 = n1.next;\n            while (n2 != null && (n1.data + n2.data) <= target) {\n                if (n1.data + n2.data == target) {\n                    ArrayList<Integer> pair = new ArrayList<>();\n                    pair.add(n1.data);\n                    pair.add(n2.data);\n                    ans.add(pair);\n                }\n                n2 = n2.next;\n            }\n            n1 = n1.next;\n        }\n        return ans;\n    }\n}', 'O(N²)', 'O(1)', 'import java.util.*;\n\npublic class Solution {\n    public static ArrayList<ArrayList<Integer>> findPairsWithGivenSum(int target, Node head) {\n        ArrayList<ArrayList<Integer>> ans = new ArrayList<>();\n        if (head == null) return ans;\n        Node left = head, right = head;\n        while (right.next != null) right = right.next;\n        while (left != null && right != null && left.data < right.data) {\n            int sum = left.data + right.data;\n            if (sum == target) {\n                ArrayList<Integer> pair = new ArrayList<>();\n                pair.add(left.data);\n                pair.add(right.data);\n                ans.add(pair);\n                left = left.next;\n                right = right.prev;\n            } else if (sum < target) {\n                left = left.next;\n            } else {\n                right = right.prev;\n            }\n        }\n        return ans;\n    }\n}', 'O(2N)', 'O(1)'),

}
